                <h3 className="text-xs font-bold uppercase tracking-wide text-gray-500">Opportunities</h3>
                {(() => {
                  const bySource = {};
                  (data.opportunities || []).forEach((o) => {
                    const src = String(o.lead_source || "").trim() || "unknown";
